def _is_constant(expr: Expr) -> bool:
    """True when an expression contains no columns and no aggregate."""
    if isinstance(expr, (Name, Star)):
        return False
    if isinstance(expr, Func) and _is_aggregate(expr.name):
        return False
    return all(_is_constant(child) for child in _children(expr))


def _validate_constants(expr: Expr, table: _Table) -> None:
    """Evaluate constant subexpressions so type errors don't depend on rows.

    This catches mistakes such as ``LOWER(1)`` even when the table is empty.
    Non-constant parts are still checked recursively.
    """
    if _is_constant(expr):
        eval_expr(expr, None, table, None)
        return
    for child in _children(expr):
        _validate_constants(child, table)

