def _is_ident_start(ch: str) -> bool:
    # "A letter" is interpreted using Unicode's definition, so ordinary
    # non-ASCII identifiers work without quoting as well.
    return ch == "_" or ch.isalpha()


def _is_ident_char(ch: str) -> bool:
    return ch == "_" or ch.isalnum()
